(()=>{
'use strict';
const terms='2026-10-07',privacy='2026-10-11';
const links='<a href="https://mowmatter.com/terms.html" target="_blank" rel="noopener">Platform Terms</a> and <a href="https://mowmatter.com/privacy.html" target="_blank" rel="noopener">Privacy Policy</a>';
function markup(audience){return `<section class="account-notice" aria-label="Account privacy and terms"><p>${audience==='customer'?'MowMatter provides your account software. Your independent lawn-care provider manages your contact details, service address, visits and invoices. Contact your provider about service terms, pricing, cancellations or changes. Creating this account does not authorize a payment or sign you up for promotional emails.':audience==='crew'?'Your business owner controls your assignments and work records. Review the privacy notice for job photos and foreground location use.':'For US lawn-care businesses. You manage your customer and crew records and must provide appropriate notices and obtain permissions for communications, photos and work-location use. Account creation does not purchase a subscription.'}</p><label class="account-agreement"><input name="account_terms" type="checkbox"><span>I agree to the ${links} for account creation or social sign-in.</span></label><p>Necessary storage supports sign-in${audience==='crew'?' and offline job work':''}. Optional website analytics and marketing are separate choices. <a href="https://mowmatter.com/cookies.html" target="_blank" rel="noopener">Your Privacy Choices</a> · <a href="https://mowmatter.com/contact.html" target="_blank" rel="noopener">Privacy requests and marketing opt-out</a></p></section>`}
function validate(form,audience){const box=form.elements.account_terms;if(!box?.checked){box?.focus();throw Error('Agree to the Platform Terms and review the Privacy Policy before creating an account or continuing with social sign-in.')}return {terms_version:terms,privacy_notice_version:privacy,account_audience:audience,terms_accepted_at:new Date().toISOString()}}
window.MowNotice={markup,validate};
const style=document.createElement('style');style.textContent='.account-notice{font-size:14px;line-height:1.6;margin:18px 0}.account-notice a{color:#145c3f;text-decoration:underline}.account-agreement{display:flex!important;gap:12px;align-items:flex-start}.account-agreement input{width:18px!important;min-height:18px!important;flex:0 0 18px;margin:4px 0}.account-notice :focus-visible{outline:3px solid #91bf2b;outline-offset:3px}';document.head.append(style);
})();
